```go
//go:build ignore

package main

import (
	"bufio"
	"fmt"
	_ "fmt"
	"os"
	"strconv"
	"strings"
	"unicode"
)

func tokenize(line string) []string {
	res := []string{}
	cur := ""
	openq := false
	for _,c := range line{
		sc := string(c)

		if openq {
			cur += sc
			if sc == "\"" {
				res = append(res, cur)
				openq = false
				cur = ""
			}
		} else if sc == "\"" {
			openq = true
			if cur != "" {
				// non quoted block
				res = append(res, cur)
				cur = ""
			}
			cur += sc
		} else {
			cur += sc 
		}
		
	}

	if cur != "" {
		res = append(res, cur)
	}

	return res
}

func unquote(s string) string {
	return s[1:len(s)-1]
}

func quote(s string) string {
	return "\"" + s + "\""
}

func getUnicodeReprs(s string) (unicode_repr string, actual_repr string, err error) {
	err = fmt.Errorf("No unicode")
	if len(s) < 3 {
		return "", "", err
	}
	s = unquote(s)
	runes := []rune(s)
	if strings.HasPrefix(s, "\\u") {
		unicode_repr = quote(s)
		val := strings.TrimPrefix(s, "\\u")
		ival, err := strconv.ParseInt(val, 16, 64)
		if err != nil {
			return "", "", err
		} else {
			actual_repr = quote(string(rune(ival)))
		}
		return unicode_repr, actual_repr, nil
	} else if len(runes) == 1 && runes[0] > unicode.MaxASCII {
		// Special character
		actual_repr := quote(s)
		unicode_repr := fmt.Sprintf("%q", s)
		return unicode_repr, actual_repr, nil
	}

	return "", "", err
	
}

func main() {
