	f,_ := os.Open(icon_file)
	defer f.Close()
	fout,_ := os.Create(icon_out_file)
	defer fout.Close()

	scanner := bufio.NewScanner(f)

	for scanner.Scan() {
		line := scanner.Text()
		// If line contains a unicode / graphical text.
		tokens := tokenize(line)
		fmt.Println(len(tokens), strings.Join(tokens, "|"))
		suffix := ""
		cnt_unicode := 0

		for i:=0; i<len(tokens); i++ {
			un, ac, err := getUnicodeReprs(tokens[i])
			if err == nil {
				// it was unicode
				cnt_unicode += 1
				if cnt_unicode > 1 {
